svg.metadata:
flowchart TB
  A["reldb.tx.wrap：開始"]
  B["コールバックの tx で読書き"]
  C["各 HaiResult.success を確認"]
  D["すべて成功：通常の値を返す"]
  E["コミットを試み、その結果を返す"]
  X["操作失敗：例外；ロールバックを試みて失敗を返す"]
  A --> B
  B --> C
  C -->|"success=true"| D
  D --> E
  C -->|"success=false"| X
  B -->|"例外"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class X stop;
